export const installBody = "<div class=\"tool-column\">\n  <button type=\"button\" class=\"lang\" id=\"lang\" lang=\"ja\">\u65e5\u672c\u8a9e</button>\n  <h1>Install Tack</h1>\n  <p data-t=\"intro\">Connect the FM-1 by USB, then press Install. It works in Chrome or Edge; the browser asks once to allow MIDI: allow it.</p>\n  <p data-t=\"warn\">Do not unplug the USB cable while writing.</p>\n  <p class=\"small\" data-t=\"direct\"></p>\n  <p class=\"small\"><span data-t=\"brick\"></span>\n    <a href=\"https://github.com/hugelton/felucca-bsp/tree/main/tools\" data-t=\"bricklink\">recovering an FM-1 that won't start</a></p>\n  <p class=\"small\" data-t=\"back\"></p>\n  <p class=\"small\"><a href=\"https://www.m-vave.com/download\" target=\"_blank\" rel=\"noopener\">www.m-vave.com/download<span class=\"sr\" data-t=\"newtab\"> (opens in a new tab)</span></a></p>\n  <div id=\"mbootopt\" hidden>\n    <p class=\"opt\"><input type=\"checkbox\" id=\"mboot\"><label for=\"mboot\" data-t=\"mboot\"></label></p>\n    <p class=\"small\"><span data-t=\"mbootwhy\"></span>\n      <a href=\"https://github.com/jvitkauskas/m-bootloader\" target=\"_blank\" rel=\"noopener\">github.com/jvitkauskas/m-bootloader<span class=\"sr\" data-t=\"newtab\"> (opens in a new tab)</span></a></p>\n  </div>\n  <p class=\"backup\"><strong data-t=\"bakh\">Back up first.</strong> <span data-t=\"confirmbak\"></span>\n    <a class=\"baklink\" href=\"../backup/\" target=\"_blank\" rel=\"noopener\"><span data-t=\"backuplink\"></span><span class=\"sr\" data-t=\"newtab\"> (opens in a new tab)</span></a></p>\n  <p><button type=\"button\" id=\"go\" disabled data-t=\"install\">Install</button></p>\n  <label class=\"sr\" for=\"bar\" data-t=\"progress\">Progress</label>\n  <progress id=\"bar\" max=\"100\" value=\"0\"></progress>\n  <p id=\"status\" role=\"status\"></p>\n  <p id=\"alert\" role=\"alert\"></p>\n  <pre id=\"log\"></pre>\n  <div id=\"portpick\" hidden>\n    <h2 data-t=\"pickh\">Is the FM-1 under another name?</h2>\n    <p class=\"small\" data-t=\"pickwhy\"></p>\n    <ul id=\"portlist\" class=\"small\"></ul>\n    <p id=\"pickstatus\" role=\"status\"></p>\n  </div>\n  <h2 data-t=\"stockh\">Back to the stock firmware</h2>\n  <p class=\"small\" data-t=\"stockwhy\"></p>\n  <ol class=\"small\">\n    <li><span data-t=\"stock1\"></span> <a href=\"https://web.archive.org/web/20261009203224id_/https://yms-file-store.oss-cn-hongkong.aliyuncs.com/software/firmware/FM-1.fwsc\">V15</a>, kept by the Internet Archive, or <a id=\"stocklink\" href=\"https://yms-file-store.oss-cn-hongkong.aliyuncs.com/software/firmware/FM-1.fwsc\">V16</a>, M-VAVE's current download. V16 also replaces the FM-1's bootloader, and Tack has not run on that bootloader, so use V15 if you plan to come back.</li>\n    <li><label for=\"stockfile\" data-t=\"stock2\">Choose the file you downloaded:</label><br><input type=\"file\" id=\"stockfile\" accept=\".fwsc\"></li>\n    <li data-t=\"stock3\"></li>\n  </ol>\n  <p><button type=\"button\" id=\"stockgo\" disabled data-t=\"stockinstall\">Install the stock firmware</button></p>\n  <h2 data-t=\"reporth\">Report a problem</h2>\n  <p class=\"small\" data-t=\"reportwhy\"></p>\n  <p><button type=\"button\" id=\"reportgo\" data-t=\"reportread\">Read the crash report</button>\n    <button type=\"button\" id=\"reportcopy\" hidden data-t=\"reportcopy\">Copy</button></p>\n  <p id=\"reportstatus\" role=\"status\"></p>\n  <label class=\"sr\" for=\"report\" data-t=\"reportlabel\">Crash report</label>\n  <textarea id=\"report\" readonly hidden rows=\"14\"></textarea>\n  <p><a href=\"../\" data-t=\"manual\">Back to Tack</a></p>\n</div>\n<dialog id=\"appask\" aria-labelledby=\"appaskh\">\n  <form method=\"dialog\">\n    <h2 id=\"appaskh\"></h2>\n    <div id=\"appaskt\"></div>\n    <div class=\"row\" id=\"appaskrow\"></div>\n  </form>\n</dialog>\n<dialog id=\"confirm\" aria-labelledby=\"confirmh\">\n  <form method=\"dialog\">\n    <h2 id=\"confirmh\" data-t=\"confirmh\"></h2>\n    <p class=\"backup\"><strong data-t=\"bakh\">Back up first.</strong> <span data-t=\"confirmbak\"></span>\n      <a class=\"baklink\" href=\"../backup/\" target=\"_blank\" rel=\"noopener\"><span data-t=\"backuplink\"></span><span class=\"sr\" data-t=\"newtab\"> (opens in a new tab)</span></a></p>\n    <p class=\"opt\"><input type=\"checkbox\" id=\"bakok\"><label for=\"bakok\" data-t=\"bakok\"></label></p>\n    <p data-t=\"confirm1\"></p>\n    <p id=\"confirmboot\" data-t=\"confirmboot\"></p>\n    <div class=\"row\"><button type=\"submit\" class=\"plain\" value=\"cancel\" data-t=\"confirmcancel\"></button>\n      <button type=\"submit\" id=\"confirmgo\" value=\"go\" disabled data-t=\"confirmgo\"></button></div>\n  </form>\n</dialog>\n<div class=\"tool-credits\">\n  <p class=\"small\">Tack is built on fm1-base and felucca-bsp, from Felucca by Leo Kuroshita (@kurogedelic), <a href=\"https://hugelton.com\" target=\"_blank\" rel=\"noopener\">H\u00fcgelton Instruments<span class=\"sr\" data-t=\"newtab\"> (opens in a new tab)</span></a>. Tack's engine is the LXR firmware by Erica Synths. USB audio's 10 channels are after Acid Moogi by Tom Perez, itself from Felucca by Leo Kuroshita, GPL-3.0.<br>\n    Fonts: Barlow Semi Condensed (SIL OFL 1.1). M-VAVE and FM-1 are trademarks of their respective owners.<br>\n    <span data-t=\"license\"></span> <a href=\"https://github.com/oikoaudio/tack\" target=\"_blank\" rel=\"noopener\">github.com/oikoaudio/tack<span class=\"sr\" data-t=\"newtab\"> (opens in a new tab)</span></a></p>\n</div>";
export const backupBody = "<div class=\"tool-column\">\n<h1>Back up Tack</h1>\n<p class=\"lede\">Save what Tack keeps to a file on this computer, and load them back later. Connect the FM-1 with a USB\ncable. This page works in Chrome or Edge, and there is nothing to install.</p>\n\n\n<div class=\"status\" id=\"statusBox\"><p id=\"status\" role=\"status\">Plug the FM-1 running Tack into this computer with a USB cable.</p><p id=\"alert\" role=\"alert\"></p></div>\n<progress id=\"bar\" max=\"100\" value=\"0\" hidden aria-label=\"Backup progress\"></progress>\n<section class=\"card\" id=\"portpick\" aria-labelledby=\"ph\" hidden>\n  <h2 id=\"ph\">Is the FM-1 under another name?</h2>\n  <p>A computer can show an FM-1's port under another device's name (a Mac remembers names by USB socket). This page asks\n  only the ports with an FM-1's usual names by itself. If your FM-1 is in this list, press Try on it.</p>\n  <ul id=\"portlist\" class=\"ports\"></ul>\n  <p id=\"pickstatus\" role=\"status\"></p>\n</section>\n\n<section class=\"card\" aria-labelledby=\"bh\">\n  <h2 id=\"bh\">Back up</h2>\n  <p>This saves everything to a <b>.tack</b> file. That includes the patterns, the song, the settings and the startup kit. Tack can keep playing. If you have\n  changes that aren't saved yet, stop Tack first so they go in the file too.</p>\n  <div class=\"row\"><button id=\"backup\" class=\"primary\" type=\"button\">Back up</button></div>\n</section>\n\n<section class=\"card\" aria-labelledby=\"rh\">\n  <h2 id=\"rh\">Restore</h2>\n  <p>This puts a backup back on Tack, and it <b>replaces everything</b> there. Stop Tack first. Tack checks the\n  whole file before anything changes. Then its screen asks <b>RESTORE FROM USB?</b> Press <kbd>SEL</kbd> on the FM-1 to restore, or\n  <kbd>HOME</kbd> to keep what you have.</p>\n  <div class=\"row\">\n    <label class=\"pick\">Choose a backup&hellip;<input type=\"file\" id=\"file\" accept=\".tack\" aria-describedby=\"fileInfo\"></label>\n    <button id=\"restore\" class=\"primary\" type=\"button\" disabled>Restore</button>\n  </div>\n  <p class=\"file\" id=\"fileInfo\" hidden></p>\n  \n  <div class=\"ask\" id=\"ask\" role=\"group\" aria-labelledby=\"askText\" hidden>\n    <p id=\"askText\"></p>\n    <div class=\"row\">\n      <button id=\"askYes\" class=\"primary\" type=\"button\">Replace everything</button>\n      <button id=\"askNo\" class=\"quiet\" type=\"button\">Cancel</button>\n    </div>\n  </div>\n</section>\n\n<ul class=\"small\">\n  <li>A backup doesn't hold the button calibration: it belongs to the FM-1.</li><li>The kit bank is not in this file. The <a href=\"../kits/\">kit bank page</a> saves the kits.</li>\n  <li>A cut cable or a damaged file changes nothing. Even a power cut during the write leaves either what was there or\n    the backup, never a mix.</li>\n  <li>The browser asks once for permission to use MIDI with SysEx. Allow it, and close other apps that use the FM-1's MIDI first.</li>\n  <li>From a terminal, <code>fm1 backup NAME</code> and <code>fm1 restore NAME</code> make and read the same file.</li>\n</ul>\n</div>";
export const kitsBody = "<div class=\"tool-column\">\n<h1>Kit bank</h1>\n<p class=\"lede\">Put kits on an FM-1 running Tack, or save the ones it has. Connect the FM-1 with a USB cable. This page\nworks in Chrome or Edge, and there is nothing to install.</p>\n\n<div class=\"status\" id=\"statusBox\"><p id=\"status\" role=\"status\">Plug the FM-1 running Tack into this computer with a USB cable.</p><p id=\"alert\" role=\"alert\"></p></div>\n<progress id=\"bar\" max=\"100\" value=\"0\" hidden aria-label=\"Progress\"></progress>\n<section class=\"card\" id=\"portpick\" aria-labelledby=\"ph\" hidden>\n  <h2 id=\"ph\">Is the FM-1 under another name?</h2>\n  <p>A computer can show an FM-1's port under another device's name (a Mac remembers names by USB socket). This page asks\n  only the ports with an FM-1's usual names by itself. If your FM-1 is in this list, press Try on it.</p>\n  <ul id=\"portlist\" class=\"ports\"></ul>\n  <p id=\"pickstatus\" role=\"status\"></p>\n</section>\n\n<section class=\"card\" aria-labelledby=\"fh\">\n  <h2 id=\"fh\">Fill the bank</h2>\n  <p>Choose <b>.SND</b> files, a folder of them, or a <b>.zip</b> of them. Kits go in sorted by name, up to 128, and they\n  <b>replace every kit in the bank</b>. Stop Tack first. Saved patterns keep their own copy of their kit, so they sound\n  the same afterwards.</p>\n  <div class=\"row\">\n    <label class=\"pick\">Choose files&hellip;<input type=\"file\" id=\"files\" multiple accept=\".snd,.zip\" aria-describedby=\"fileInfo\"></label>\n    <label class=\"pick\">Choose a folder&hellip;<input type=\"file\" id=\"folder\" webkitdirectory aria-describedby=\"fileInfo\"></label>\n    <button id=\"fill\" class=\"primary\" type=\"button\" disabled>Replace the bank</button>\n  </div>\n  <p class=\"file\" id=\"fileInfo\" hidden></p>\n  <div class=\"ask\" id=\"ask\" role=\"group\" aria-labelledby=\"askText\" hidden>\n    <p id=\"askText\"></p>\n    <div class=\"row\">\n      <button id=\"askYes\" class=\"primary\" type=\"button\">Replace every kit</button>\n      <button id=\"askNo\" class=\"quiet\" type=\"button\">Cancel</button>\n    </div>\n  </div>\n</section>\n\n<section class=\"card\" aria-labelledby=\"sh\">\n  <h2 id=\"sh\">Save the bank</h2>\n  <p>This saves every kit to a <b>.zip</b>, which you can choose above to put them back. Stop Tack first.</p>\n  <div class=\"row\"><button id=\"save\" class=\"primary\" type=\"button\">Save the bank</button></div>\n</section>\n\n<ul class=\"small\">\n  <li>Tack comes with no kits. <a href=\"https://www.ericasynths.lv/news/fresh-kits-and-patterns-lxr-02-hrtl\">Erica Synths publishes kit packs</a> for the LXR-02, and <a href=\"../../plugin/\">the Tack plugin</a> saves kits in the same format.</li>\n  <li>Keep the cable in while the bank fills. If it comes out, plug it back in and press Replace the bank again.</li>\n  <li>The browser asks once for permission to use MIDI with SysEx. Allow it, and close other apps that use the FM-1's MIDI first.</li>\n  <li>From a terminal, <code>fm1 kits FOLDER</code> does the same as Replace the bank, and <code>fm1 backup NAME</code> saves the bank to a folder.</li>\n</ul>\n</div>";
